/bin/zsh -lc "cat money.mjs; cat windows.mjs; node --input-type=module <<'JS'
import assert from 'node:assert/strict';
import {discountedTotal, splitCents} from './money.mjs';
import {overlaps, mergeWindows} from './windows.mjs';
for (let cents=0;cents<=200;cents++) for(let percent=0;percent<=100;percent++) assert.equal(discountedTotal(cents,percent),Math.round(cents*(1-percent/100)));
assert.equal(discountedTotal(1,50),1);
for(let total=0;total<=200;total++) for(let people=1;people<=30;people++) {
 const result=splitCents(total,people);
 assert.equal(result.length,people);
 assert.equal(result.reduce((a,b)=>a+b,0),total);
 result.forEach((value,i)=>assert.equal(value,Math.floor(total/people)+(i<total%people?1:0)));
}
for(let a=-3;a<3;a++) for(let b=a+1;b<=4;b++) for(let c=-3;c<3;c++) for(let d=c+1;d<=4;d++) assert.equal(overlaps({start:a,end:b},{start:c,end:d}),Math.max(a,c)<Math.min(b,d));
const input=Object.freeze([Object.freeze({start:5,end:7}),Object.freeze({start:1,end:3}),Object.freeze({start:3,end:6}),Object.freeze({start:9,end:10})]);
const output=mergeWindows(input);
assert.deepEqual(output,[{start:1,end:7},{start:9,end:10}]);
for(const item of output) assert.ok("'!input.includes(item));
output[0].end=99;
assert.equal(input[1].end,3);
assert.deepEqual(mergeWindows([]),[]);
const singleton={start:0,end:1};
assert.notEqual(mergeWindows([singleton])[0],singleton);
assert.deepEqual(mergeWindows([{start:1,end:8},{start:2,end:3}]),[{start:1,end:8}]);
console.log('"'Independent verification passed: discount grid, 6030 splits, exhaustive interval pairs, merge ordering, frozen inputs, and object independence.');
JS"

